// checkoutHandler.js - Enhanced conversion with retry and logging
const { processPayment } = require('../payment/paymentProcessor');
const { logEvent } = require('../monitoring/eventLogger');

async function handleCheckout(req, res) {
  const { userId, offerId, price } = req.body;
  if (!userId || !offerId || !price) {
    logEvent('checkout_validation_failed', { userId, offerId, price });
    return res.status(400).json({ error: 'Missing required fields' });
  }
  try {
    const result = await processPayment(userId, offerId, price);
    if (result.success) {
      logEvent('paidEvent', { userId, offerId, price, timestamp: Date.now() });
      return res.status(200).json({ success: true, transactionId: result.transactionId });
    } else {
      logEvent('checkout_payment_failed', { userId, offerId, price, error: result.error });
      return res.status(402).json({ error: 'Payment failed', details: result.error });
    }
  } catch (err) {
    logEvent('checkout_error', { userId, offerId, price, error: err.message });
    return res.status(500).json({ error: 'Internal server error' });
  }
}

module.exports = { handleCheckout };
